package com.sumedha.commerce.product.entity; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="brands") public class Brand{@Id @Column(name="brand_id") private UUID id;private String name,slug,description;private boolean active;@Column(name="created_at") private Instant createdAt;@Column(name="updated_at") private Instant updatedAt;protected Brand(){}public Brand(String n,String s,String d){id=UUID.randomUUID();name=n;slug=s;description=d;active=true;createdAt=Instant.now();updatedAt=createdAt;}@PreUpdate void touch(){updatedAt=Instant.now();}public UUID getId(){return id;}public String getName(){return name;}public String getSlug(){return slug;}public String getDescription(){return description;}public boolean isActive(){return active;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void update(String n,String s,String d,boolean a){name=n;slug=s;description=d;active=a;}}
